  $q=db()->prepare("SELECT MIN(appointment_date) FROM appointments WHERE customer_id=? AND appointment_date>=CURDATE() AND status IN ('pending','confirmed')".($extra?' AND therapist_id=?':''));$q->execute($params);$nextVisit=$q->fetchColumn();
  $q=db()->prepare("SELECT t.* FROM transactions t WHERE t.customer_id=? ORDER BY t.created_at DESC LIMIT 10");$q->execute([$id]);$payments=$q->fetchAll();
  $sessionSql='SELECT ss.*,srv.name service_name,th.full_name therapist_name FROM sessions ss JOIN services srv ON srv.id=ss.service_id JOIN therapists th ON th.id=ss.therapist_id WHERE ss.customer_id=?';$sessionParams=[$id];if(is_therapist()){$sessionSql.=' AND ss.therapist_id=?';$sessionParams[]=(int)(current_user()['therapist_id']??0);}$sessionSql.=' ORDER BY ss.session_date DESC LIMIT 50';$shq=db()->prepare($sessionSql);$shq->execute($sessionParams);$sessionHistory=$shq->fetchAll();
