><?=h($a['service_name'])?></td><td><?=h($a['therapist_name'])?></td><td><?=status_badge($a['status'])?></td><td><?=h($a['notes']?:'—')?><?php $ss=db()->prepare('SELECT id,session_notes,recommendations FROM sessions WHERE appointment_id=? LIMIT 1');$ss->execute([$a['id']]);$sn=$ss->fetch();if($sn):?><div class="small-muted mt-1"><?=h(mb_substr($sn['session_notes']?:$sn['recommendations'],0,90))?> <a href="<?=h(app_page_url('session',['id'=>$sn['id']]))?>">View notes</a></div><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><div class="card mt-3"><div class="card-header">Service session records</div><div class="table-responsive"><table class="table"><thead><tr><th>Session date</th><th>Service</th><th>Therapist</th><th>Notes</th><th></th></tr></thead><tbody><?php if(!$sessionHistory)echo table_empty(5,'No session records yet.');foreach($sessionHistory as $sh):?><tr><td><?=date_label($sh['session_date'],'M j, Y g:i A')?></td><td><?=h($sh['service_name'])?><div class="small-muted"><?=h($sh['duration_minutes'])?> min</div></td><td><?=h($sh['therapist_name'])?></td><td><?=h(mb_substr($sh['session_notes']?:$sh['customer_concerns'],0,100)?:'—')?></td><td class="text-end"><a class="btn btn-sm btn-light" href="<?=h(app_page_url('session',['id'=>$sh['id']]))?>"><i class="bi bi-journal-text"></i></a></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
